window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4db6f7ffc6cc86c8"]={"versions": [{"id": "FIG-4db6f7ffc6cc86c8", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Übersichtsdiagramm der AUTOSAR Adaptive Platform Methodology zur Darstellung der hierarchischen Zerlegung des Gesamtmethodologie-Workflows. Das Diagramm modelliert mittels UML-artiger Kompositions- bzw. Schachtelungsbeziehungen («nesting») die Aufteilung der übergeordneten Methodologie (<code>Adaptive Methodology Overview</code>) in spezialisierte methodische Teilaktivitäten und Sub-Workflows.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Knoten ist der zirkuläre Prozessknoten <code>Adaptive Methodology Overview</code>. Um diesen herum sind über ungerichtete Assoziationen mit Kompositionsraute («nesting») folgende Aktivitäts- und Artefaktblöcke angebunden:</p>\n<ul class=\"fig-list\">\n<li><code>Develop a Service Interface Description</code></li>\n<li><code>Develop Adaptive Application Software</code></li>\n<li><code>Develop Platform-level Application Software</code></li>\n<li><code>Integrate Software</code></li>\n<li><code>Select OS</code></li>\n<li><code>Define and configure</code></li>\n<li><code>Create Application Manifest</code></li>\n<li><code>Define and Configure Service Instances</code></li>\n<li><code>Set Up Machine</code></li>\n<li><code>Deploy SW Package</code></li>\n</ul>\n<p class=\"fig-p\">Jedes Aktivitätssymbol setzt sich aus symbolischen Modellelementen (Ovale für Aktivitäten/Zustände, Dokumentensymbole für Manifeste/Beschreibungen und Blockpfeile für Transformationsschritte) zusammen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturzerlegung (Nesting) der Gesamtmethodologie dar. Die Pfeilschleife im zentralen Knoten symbolisiert den iterativen Charakter des AUTOSAR-Adaptive-Entwicklungszyklus. Es werden keine gerichteten Kontrollflüsse oder Nachrichtensequenzen zwischen den Subaktivitäten modelliert; die Aktivitäten kapseln eigenständige Arbeitsabläufe, die parallel oder iterativ verschränkt durchlaufen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normatives Top-Level-Strukturmodell für die Methodologie der AUTOSAR Adaptive Platform. Entwickler und Werkzeughersteller müssen die definierten Subaktivitäten als modulare Prozessbausteine implementieren. Die Trennung zwischen Anwendungssoftware (<code>Develop Adaptive Application Software</code>) und Plattformsoftware (<code>Develop Platform-level Application Software</code>) sowie die spezifischen Schritte für Manifest-Erstellung und Paket-Deployment (<code>Deploy SW Package</code>) strukturieren die Prozessketten und Rollenverteilung.</p>"}, {"id": "FIG-f4d70dbeacb6a1a6", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Übersichtsdiagramm der AUTOSAR Adaptive Platform Methodology zur Darstellung der hierarchischen Zerlegung des Gesamtmethodologie-Workflows. Das Diagramm modelliert mittels UML-artiger Kompositions- bzw. Schachtelungsbeziehungen («nesting») die Aufteilung der übergeordneten Methodologie (<code>Adaptive Methodology Overview</code>) in spezialisierte methodische Teilaktivitäten und Sub-Workflows.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Knoten ist <code>Adaptive Methodology Overview</code>. Die über «nesting» angebundenen Teilaktivitäten umfassen:</p>\n<ul class=\"fig-list\">\n<li><code>Develop a Service Interface Description</code></li>\n<li><code>Develop Adaptive Software</code></li>\n<li><code>Design communication between Classic and Adaptive Platform</code></li>\n<li><code>Integrate Software</code></li>\n<li><code>Select OS</code></li>\n<li><code>Define and configure</code></li>\n<li><code>Create Application Manifest</code></li>\n<li><code>Define and Configure Service Instances</code></li>\n<li><code>Set Up Machine</code></li>\n<li><code>Create SoftwareCluster</code></li>\n<li><code>Deploy SoftwareCluster</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturzerlegung (Nesting) der Gesamtmethodologie dar. Die Pfeilschleife im zentralen Knoten symbolisiert den iterativen Charakter des AUTOSAR-Adaptive-Entwicklungszyklus. Es werden keine gerichteten Kontrollflüsse oder Nachrichtensequenzen zwischen den Subaktivitäten modelliert; die Aktivitäten kapseln eigenständige Arbeitsabläufe, die parallel oder iterativ verschränkt durchlaufen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die methodische Strukturierung unter Berücksichtigung von SoftwareClustern als standardisierte Bereitstellungseinheiten sowie der plattformübergreifenden Interoperabilität zwischen Classic und Adaptive Platform. Die Zusammenfassung der Softwareentwicklung zu <code>Develop Adaptive Software</code> vereinheitlicht die Entwicklungsprozesse von Plattform- und Anwendungsdiensten.</p>"}, {"id": "FIG-8ad780b62e9b2dbb", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Übersichtsdiagramm der AUTOSAR Adaptive Platform Methodology zur Darstellung der hierarchischen Zerlegung des Gesamtmethodologie-Workflows. Das Diagramm modelliert mittels UML-artiger Kompositions- bzw. Schachtelungsbeziehungen («nesting») die Aufteilung der übergeordneten Methodologie (<code>Adaptive Methodology Overview</code>) in spezialisierte methodische Teilaktivitäten und Sub-Workflows.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Knoten ist <code>Adaptive Methodology Overview</code>. Folgende per «nesting» verknüpfte Aktivitäten sind enthalten:</p>\n<ul class=\"fig-list\">\n<li><code>Develop a Service Interface Description</code></li>\n<li><code>Develop Adaptive Software</code></li>\n<li><code>Develop the communication structure by means of MachineDesign</code></li>\n<li><code>Create Diagnostic Mapping</code></li>\n<li><code>Design communication between Classic and Adaptive Platform</code></li>\n<li><code>Integrate Software</code></li>\n<li><code>Select OS</code></li>\n<li><code>Define and configure</code></li>\n<li><code>Create Application Manifest</code></li>\n<li><code>Define and Configure Service Instances</code></li>\n<li><code>Set Up Initial Machine</code></li>\n<li><code>Create Software Package</code></li>\n<li><code>Provide and manage Software Packages</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturzerlegung (Nesting) der Gesamtmethodologie dar. Die Pfeilschleife im zentralen Knoten symbolisiert den iterativen Charakter des AUTOSAR-Adaptive-Entwicklungszyklus. Es werden keine gerichteten Kontrollflüsse oder Nachrichtensequenzen zwischen den Subaktivitäten modelliert; die Aktivitäten kapseln eigenständige Arbeitsabläufe, die parallel oder iterativ verschränkt durchlaufen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodologie verankert formale Schritte für das Maschinendesign (<code>MachineDesign</code>), Diagnose-Mapping sowie den durchgängigen Paketierungs- und Auslieferungslebenszyklus (<code>Software Packages</code>). Das initiale Aufsetzen der Maschine (<code>Set Up Initial Machine</code>) wird als eigenständiger methodischer Ausgangspunkt etabliert.</p>"}, {"id": "FIG-ba3261ed5bf258d9", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Übersichtsdiagramm der AUTOSAR Adaptive Platform Methodology zur Darstellung der hierarchischen Zerlegung des Gesamtmethodologie-Workflows. Das Diagramm modelliert mittels UML-artiger Kompositions- bzw. Schachtelungsbeziehungen («nesting») die Aufteilung der übergeordneten Methodologie (<code>Adaptive Methodology Overview</code>) in spezialisierte methodische Teilaktivitäten und Sub-Workflows.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Knoten ist <code>Adaptive Methodology Overview</code>. Folgende per «nesting» verknüpfte Aktivitäten sind enthalten:</p>\n<ul class=\"fig-list\">\n<li><code>Develop a Service Interface Description</code></li>\n<li><code>Develop Adaptive Software</code></li>\n<li><code>Develop the communication structure by means of MachineDesign</code></li>\n<li><code>Create Diagnostic Mapping</code></li>\n<li><code>Design communication between Classic and Adaptive Platform</code></li>\n<li><code>Integrate Software</code></li>\n<li><code>Select OS</code></li>\n<li><code>Define and configure</code></li>\n<li><code>Create Execution Manifest</code></li>\n<li><code>Define and Configure Service Instances</code></li>\n<li><code>Set Up Initial Machine</code></li>\n<li><code>Create Software Package</code></li>\n<li><code>Provide and manage Software Packages</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturzerlegung (Nesting) der Gesamtmethodologie dar. Die Pfeilschleife im zentralen Knoten symbolisiert den iterativen Charakter des AUTOSAR-Adaptive-Entwicklungszyklus. Es werden keine gerichteten Kontrollflüsse oder Nachrichtensequenzen zwischen den Subaktivitäten modelliert; die Aktivitäten kapseln eigenständige Arbeitsabläufe, die parallel oder iterativ verschränkt durchlaufen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Anpassung präzisiert die Terminologie der Manifeste in der Methodologie: Der Fokus liegt spezifisch auf dem <code>Execution Manifest</code> für das Deployment und die Prozesskonfiguration auf Instanzebene.</p>"}, {"id": "FIG-949beeef2f5ae38e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Übersichtsdiagramm der AUTOSAR Adaptive Platform Methodology zur Darstellung der hierarchischen Zerlegung des Gesamtmethodologie-Workflows. Das Diagramm modelliert mittels UML-artiger Kompositions- bzw. Schachtelungsbeziehungen («nesting») die Aufteilung der übergeordneten Methodologie (<code>Adaptive Methodology Overview</code>) in spezialisierte methodische Teilaktivitäten und Sub-Workflows.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Knoten ist <code>Adaptive Methodology Overview</code>. Folgende per «nesting» angebundene methodische Aktivitäten sind dargestellt:</p>\n<ul class=\"fig-list\">\n<li><code>Develop a Service Interface Description</code></li>\n<li><code>Develop Adaptive Software</code></li>\n<li><code>Develop the communication structure by means of MachineDesign</code></li>\n<li><code>Create Diagnostic Mapping</code></li>\n<li><code>Design communication between Classic and Adaptive Platform</code></li>\n<li><code>Integrate Software</code></li>\n<li><code>Select OS</code></li>\n<li><code>Define machine...</code></li>\n<li><code>Create Execution...</code></li>\n<li><code>Finalize machine configuration</code></li>\n<li><code>Define and Configure Service Instances</code></li>\n<li><code>Set Up Initial Machine</code></li>\n<li><code>Create Software Package</code></li>\n<li><code>Provide and manage Software Packages</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturzerlegung (Nesting) der Gesamtmethodologie dar. Die Pfeilschleife im zentralen Knoten symbolisiert den iterativen Charakter des AUTOSAR-Adaptive-Entwicklungszyklus. Es werden keine gerichteten Kontrollflüsse oder Nachrichtensequenzen zwischen den Subaktivitäten modelliert; die Aktivitäten kapseln eigenständige Arbeitsabläufe, die parallel oder iterativ verschränkt durchlaufen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodologie institutionalisiert den expliziten Schritt <code>Finalize machine configuration</code> als formalen Abschluss der Maschinen- und Integrationskonfiguration vor der Bereitstellung.</p>"}, {"id": "FIG-4dc0074d5baf0c59", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Übersichtsdiagramm der AUTOSAR Adaptive Platform Methodology zur Darstellung der hierarchischen Zerlegung des Gesamtmethodologie-Workflows. Das Diagramm modelliert mittels UML-artiger Kompositions- bzw. Schachtelungsbeziehungen («nesting») die Aufteilung der übergeordneten Methodologie (<code>Adaptive Methodology Overview</code>) in spezialisierte methodische Teilaktivitäten und Sub-Workflows.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Knoten ist <code>Adaptive Methodology Overview</code>. Folgende per «nesting» angebundene methodische Aktivitäten sind dargestellt:</p>\n<ul class=\"fig-list\">\n<li><code>Develop a Service Interface Description</code></li>\n<li><code>Develop Adaptive Software</code></li>\n<li><code>Develop the communication structure by means of MachineDesign</code></li>\n<li><code>Create Diagnostic Mapping</code></li>\n<li><code>Design communication between Classic and Adaptive Platform</code></li>\n<li><code>Integrate Software</code></li>\n<li><code>Select OS</code></li>\n<li><code>Define machine...</code></li>\n<li><code>Create Execution...</code></li>\n<li><code>Finalize machine configuration</code></li>\n<li><code>Define and Configure Service Instances</code></li>\n<li><code>Set Up Initial Machine</code></li>\n<li><code>Create Software Package</code></li>\n<li><code>Provide and manage Software Packages</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturzerlegung (Nesting) der Gesamtmethodologie dar. Die Pfeilschleife im zentralen Knoten symbolisiert den iterativen Charakter des AUTOSAR-Adaptive-Entwicklungszyklus. Es werden keine gerichteten Kontrollflüsse oder Nachrichtensequenzen zwischen den Subaktivitäten modelliert; die Aktivitäten kapseln eigenständige Arbeitsabläufe, die parallel oder iterativ verschränkt durchlaufen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodologie institutionalisiert den expliziten Schritt <code>Finalize machine configuration</code> als formalen Abschluss der Maschinen- und Integrationskonfiguration vor der Bereitstellung.</p>"}], "trans": [{"from": "FIG-4db6f7ffc6cc86c8", "to": "FIG-f4d70dbeacb6a1a6", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ersetzung des Aktivitäten-Subgraphen <code>Develop Adaptive Application Software</code> und <code>Develop Platform-level Application Software</code> durch den zusammenfassenden Subgraphen <code>Develop Adaptive Software</code>.</li>\n<li>Hinzufügung des neuen Aktivitätsbereichs <code>Design communication between Classic and Adaptive Platform</code>.</li>\n<li>Ersetzung von <code>Deploy SW Package</code> durch <code>Deploy SoftwareCluster</code>.</li>\n<li>Hinzufügung der Aktivität <code>Create SoftwareCluster</code>.</li>\n</ul>"}, {"from": "FIG-f4d70dbeacb6a1a6", "to": "FIG-8ad780b62e9b2dbb", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Hinzufügung der Aktivitäts-Subgraphen <code>Develop the communication structure by means of MachineDesign</code> und <code>Create Diagnostic Mapping</code>.</li>\n<li>Umbenennung und methodische Neuausrichtung von <code>Set Up Machine</code> zu <code>Set Up Initial Machine</code>.</li>\n<li>Ersetzung von <code>Deploy SoftwareCluster</code> und <code>Create SoftwareCluster</code> durch <code>Provide and manage Software Packages</code> sowie <code>Create Software Package</code>.</li>\n<li>Wiederaufnahme von <code>Create Application Manifest</code> in die Übersicht.</li>\n</ul>"}, {"from": "FIG-8ad780b62e9b2dbb", "to": "FIG-ba3261ed5bf258d9", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Umbenennung des Aktivitäten-Icons von <code>Create Application Manifest</code> zu <code>Create Execution Manifest</code>.</li>\n</ul>"}, {"from": "FIG-ba3261ed5bf258d9", "to": "FIG-949beeef2f5ae38e", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ersetzung der Aktivität <code>Create Execution Manifest</code> auf der rechten Seite durch <code>Finalize machine configuration</code>.</li>\n<li>Verschiebung von <code>Create Execution Manifest</code> in die untere Reihe der Subaktivitäten (wo zuvor <code>Define and configure...</code> stand).</li>\n<li>Umbenennung von <code>Define and configure...</code> zu <code>Define machine...</code>.</li>\n</ul>"}, {"from": "FIG-949beeef2f5ae38e", "to": "FIG-4dc0074d5baf0c59", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
